detaileddescription.para:
使用示例： //创建SSL上下文（用于TLS）
ssl_contextctx(ssl_method::TLS_CLIENT);
ctx.load_verify_locations("ca-bundle.crt");

//创建SMTPsocket
smtp_socketsmtp;

//连接到QQ邮箱（STARTTLS）
smtp.connect("smtp.qq.com",ports::smtp,"example.com",
smtp_socket::tls_mode::starttls,nullptr,&ctx);

//认证
smtp.authenticate("username@qq.com","password",
smtp_socket::auth_method::login);

//构建邮件
smtp_messagemsg;
msg.from="sender@qq.com";
msg.to={"recipient@example.com"};
msg.subject="TestEmail";
msg.body="Hello,thisisatestemail!";
msg.is_html=false;

//发送邮件
smtp.send(msg);

//断开连接
smtp.disconnect();
